package com.android.tools.lint.checks;

import com.android.ide.common.resources.ResourceItem;
import com.android.ide.common.resources.ResourceRepository;
import com.android.ide.common.resources.configuration.FolderConfiguration;
import com.android.ide.common.resources.configuration.ResourceQualifier;
import com.android.ide.common.resources.configuration.VersionQualifier;
import com.android.resources.ResourceNamespace;
import com.android.resources.ResourceUrl;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.ResourceXmlDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.tools.lint.detector.api.XmlScannerConstants;
import com.google.common.collect.ListMultimap;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;
import java.util.Collection;
import java.util.List;

public class ManifestResourceDetector extends ResourceXmlDetector {
    private static final String ANDROID_URI = "http://schemas.android.com/apk/res/android";

    public static final Issue ISSUE = Issue.create(...)

    @Override
    public Collection<String> getApplicableAttributes() { return XmlScannerConstants.ALL; }

    @Override
    public void visitAttribute(XmlContext context, Attr attribute) {
        if (!ANDROID_URI.equals(attribute.getNamespaceURI())) return;
        String value = attribute.getValue();
        if (value.isEmpty() || value.charAt(0) != '@') return;
        ResourceUrl url = ResourceUrl.parse(value);
        if (url == null || url.isCreate() || url.isTheme() || url.isFramework() || url.type == null) return;

        ResourceRepository resources = context.getDriver().getClient().getResources(context.getMainProject(), true);
        if (resources == null) return;

        ListMultimap<String, ResourceItem> map = resources.getResources(ResourceNamespace.RES_AUTO, url.type);
        if (map == null) return;
        List<ResourceItem> items = map.get(url.name);
        if (items == null || items.isEmpty()) return;

        for (ResourceItem item : items) {
            FolderConfiguration config = item.getConfiguration();
            if (!isVersionOnly(config)) {
                String attrName = attribute.getLocalName();
                Element owner = attribute.getOwnerElement();
                String elementName = owner.getLocalName();
                if ("application".equals(elementName) && ("icon".equals(attrName) || "label".equals(attrName))) {
                    return;
                }
                String message = String.format("The resource `@%1$s/%2$s` has variants across configurations, but resources referenced from the manifest cannot vary by configuration (except by version)", url.type.getName(), url.name);
                context.report(ISSUE, context.getValueLocation(attribute), message);
                return;
            }
        }
    }

    private static boolean isVersionOnly(FolderConfiguration config) {
        if (config == null) return true;
        for (ResourceQualifier qualifier : config.getQualifiers()) {
            if (qualifier != null && qualifier.isValid() && !(qualifier instanceof VersionQualifier)) {
                return false;
            }
        }
        return true;
    }
}

